const baseClientLayerV10=clientLayer;clientLayer=function(ctx={}){const c=clients.find(x=>x.id===ctx.id)||clients[0],def=baseClientLayerV10(ctx);const brand=`<div class="layer-client-brand-v10"><span class="client-avatar-v10">${c.logo?`<img src="${c.logo}" alt="${escapeHtmlV8(c.name)} logo">`:escapeHtmlV8(initialsV10(c.name))}</span><span><strong>${escapeHtmlV8(c.name)}</strong><small>${escapeHtmlV8(c.registration||c.id)}</small></span></div>`;def.html=def.html.replace(`<div class="layer-head-copy"><div class="eyebrow">`, `<div class="layer-head-copy">${brand}<div class="eyebrow">`);def.html=def.html.replace('<div class="layer-head-actions">','<div class="layer-head-actions"><button class="btn secondary" type="button" data-client-profile-edit="'+c.id+'">Edit profile</button>');return def};

function renderOnboardingV10(){const tbody=document.querySelector('#page-onboarding .onboarding-table tbody');if(!tbody)return;const stage=document.getElementById('onboardingStageFilter')?.value||'all',risk=document.getElementById('onboardingRiskFilter')?.value||'all';const apps=onboardingApplicationsV10.filter(a=>(stage==='all'||a.stage===stage)&&(risk==='all'||a.risk===risk));tbody.innerHTML=apps.map(a=>`<tr data-onboarding-row="${a.id}"><td><strong>${escapeHtmlV8(a.name)}</strong><small>${a.id} · ${escapeHtmlV8(a.type)}</small></td><td>${escapeHtmlV8(a.channel)}</td><td><span class="tag ${tagClassV10(a.stage)}">${escapeHtmlV8(a.stage)}</span></td><td><span class="tag ${tagClassV10(a.identity)}">${escapeHtmlV8(a.identity)}</span></td><td><span class="tag ${tagClassV10(a.screening)}">${escapeHtmlV8(a.screening)}</span></td><td><span class="tag ${tagClassV10(a.funds)}">${escapeHtmlV8(a.funds)}</span></td><td><strong>${a.docsDone} / ${a.docsTotal}</strong><small>${a.docsDone>=a.docsTotal?'Complete':`${a.docsTotal-a.docsDone} outstanding`}</small></td><td>${escapeHtmlV8(a.owner)}</td><td><strong class="${/overdue/i.test(a.sla)?'attention':''}">${escapeHtmlV8(a.sla)}</strong><small>${escapeHtmlV8(a.slaState)}</small></td><td><button class="row-action" data-onboarding-id="${a.id}" type="button">Open →</button></td></tr>`).join('');tbody.querySelectorAll('[data-onboarding-row]').forEach(r=>r.addEventListener('click',e=>{if(e.target.closest('button'))return;openSecondLayer('onboarding',{id:r.dataset.onboardingRow})}));tbody.querySelectorAll('[data-onboarding-id]').forEach(b=>b.addEventListener('click',e=>{e.stopPropagation();openSecondLayer('onboarding',{id:b.dataset.onboardingId})}));const k=document.querySelector('#page-onboarding .onboarding-kpis article:first-child strong');if(k)k.textContent=onboardingApplicationsV10.filter(a=>a.stage!=='Active').length;const cmd=document.querySelector('#page-onboarding .onboarding-command-primary strong');if(cmd)cmd.textContent=`${onboardingApplicationsV10.filter(a=>a.stage!=='Active').length} applications are actively moving through KYC`}
function appV10(id){return onboardingApplicationsV10.find(a=>a.id===id)||onboardingApplicationsV10[0]}
function kycStageIndexV10(stage){return ['Application','Identity & Documents','Screening','Compliance Review','Activation','Active'].indexOf(stage)}
function onboardingLayerV10(ctx={}){const a=appV10(ctx.id),idx=kycStageIndexV10(a.stage),steps=['Application','Identity & Documents','Screening','Compliance Review','Activation','Active'];const tracker=steps.map((s,i)=>`<div class="${i<idx?'done':i===idx?(a.risk==='High'&&a.stage==='Compliance Review'?'blocked':'current'):''}"><span>0${i+1}</span><strong>${s}</strong><small>${i<idx?'Complete':i===idx?'Current':'Pending'}</small></div>`).join('');const notes=(a.timeline||[]).map(x=>`<div><time>${escapeHtmlV8(x[0])}</time><span><strong>${escapeHtmlV8(x[1])}</strong><small>${escapeHtmlV8(x[2])}</small></span></div>`).join('');return {parent:'onboarding',html:layerShell({parent:'onboarding',eyebrow:'APPLICATION TRACKER · SECOND LEVEL',title:`${a.id} · ${escapeHtmlV8(a.name)}`,subtitle:`${escapeHtmlV8(a.type)} · ${escapeHtmlV8(a.channel)} · Controlled KYC and onboarding case with live stage, owner, evidence and decision history.`,stats:[['Stage',a.stage,`${a.progress}% complete`],['Risk',a.risk,'Risk-based due diligence'],['Documents',`${a.docsDone} / ${a.docsTotal}`,a.docsDone>=a.docsTotal?'Complete':'Evidence outstanding'],['Owner',a.owner,'Current accountable user'],['SLA',a.sla,a.slaState]],actions:`<button class="btn secondary" type="button" data-kyc-action="edit" data-id="${a.id}">Edit application</button><button class="btn primary" type="button" data-kyc-action="advance" data-id="${a.id}">${a.stage==='Active'?'Active':a.stage==='Activation'?'Activate client':'Move to next stage'}</button>`,tabs:[{id:'journey',label:'Journey & next action',body:`<div class="kyc-tracker-v10">${tracker}</div><div class="layer-grid"><article class="layer-panel layer-span-8"><div class="layer-panel-head"><div><span class="layer-kicker">NEXT REQUIRED ACTION</span><h2>${escapeHtmlV8(a.next)}</h2></div></div><div class="layer-panel-body"><div class="kyc-action-bar-v10"><button class="btn secondary" type="button" data-kyc-action="request" data-id="${a.id}">Request evidence</button><button class="btn secondary" type="button" data-kyc-action="note" data-id="${a.id}">Add case note</button><label>Owner<select class="kyc-owner-v10" data-kyc-owner="${a.id}">${['C. Dube','P. Ncube','L. Chuma','R. Marufu','S. Moyo'].map(x=>`<option ${x===a.owner?'selected':''}>${x}</option>`).join('')}</select></label></div></div></article><aside class="layer-panel layer-span-4"><div class="layer-panel-head"><div><span class="layer-kicker">CASE CONTROL</span><h2>${a.risk==='High'?'Enhanced review':'Standard review'}</h2></div></div><div class="layer-panel-body"><div class="layer-list"><div><span><strong>Identity</strong><small>Legal existence / identity</small></span><em>${escapeHtmlV8(a.identity)}</em></div><div><span><strong>AML / PEP</strong><small>Latest screening state</small></span><em>${escapeHtmlV8(a.screening)}</em></div><div><span><strong>Source of funds</strong><small>Evidence state</small></span><em>${escapeHtmlV8(a.funds)}</em></div></div></div></aside></div>`},{id:'checks',label:'KYC / AML checks',body:`<article class="layer-panel"><div class="layer-panel-head"><div><span class="layer-kicker">CONTROL CHECKLIST</span><h2>Evidence-backed verification state</h2></div></div>${layerTable(['Control','Result','Evidence','State'],[`<tr><td><strong>Legal identity</strong></td><td>${escapeHtmlV8(a.identity)}</td><td>Entity / identity record</td><td>${tagClassV10(a.identity)==='green'?'Complete':'Open'}</td></tr>`,`<tr><td><strong>Beneficial ownership</strong></td><td>${idx>=2?'Captured':'In progress'}</td><td>Ownership declaration</td><td>${idx>=2?'Complete':'Open'}</td></tr>`,`<tr><td><strong>Sanctions / PEP</strong></td><td>${escapeHtmlV8(a.screening)}</td><td>Screening record</td><td>${/clear/i.test(a.screening)?'Complete':'Review'}</td></tr>`,`<tr><td><strong>Source of funds</strong></td><td>${escapeHtmlV8(a.funds)}</td><td>Bank / wealth evidence</td><td>${/approved|received/i.test(a.funds)?'Complete':'Open'}</td></tr>`,`<tr><td><strong>Required documents</strong></td><td>${a.docsDone} / ${a.docsTotal}</td><td>Document vault</td><td>${a.docsDone>=a.docsTotal?'Complete':'Open'}</td></tr>`])}</article>`},{id:'activity',label:'Case history',body:`<article class="layer-panel"><div class="layer-panel-head"><div><span class="layer-kicker">APPLICATION HISTORY</span><h2>Track every action</h2></div><button class="text-btn" type="button" data-kyc-action="note" data-id="${a.id}">Add note →</button></div><div class="layer-panel-body"><div class="kyc-note-list-v10">${notes||'<div><time>—</time><span><strong>No case notes yet</strong><small>Add the first controlled case note.</small></span></div>'}</div></div></article>`},{id:'activation',label:'Activation',body:`<div class="layer-grid"><article class="layer-panel layer-span-7"><div class="layer-panel-head"><div><span class="layer-kicker">ACTIVATION GATE</span><h2>Ready to become an active client?</h2></div></div><div class="layer-panel-body"><div class="layer-list"><div><span><strong>Identity / legal existence</strong><small>Mandatory</small></span><em>${/verified/i.test(a.identity)?'Pass':'Open'}</em></div><div><span><strong>Screening</strong><small>Sanctions / PEP</small></span><em>${/clear/i.test(a.screening)?'Pass':'Review'}</em></div><div><span><strong>Source of funds</strong><small>Risk-based evidence</small></span><em>${/approved/i.test(a.funds)?'Pass':'Open'}</em></div><div><span><strong>Documents</strong><small>Required evidence</small></span><em>${a.docsDone>=a.docsTotal?'Pass':'Open'}</em></div></div></div></article></div>`}]})}}
